class Solution {
public int shortestBridge(int[][] grid){int n=grid.length;boolean[][]seen=new boolean[n][n];Deque<int[]>first=new ArrayDeque<>(),q=new ArrayDeque<>();outer:for(int r=0;r<n;r++)for(int c=0;c<n;c++)if(grid[r][c]==1){first.add(new int[]{r,c});seen[r][c]=true;break outer;}int[]ds={-1,0,1,0,-1};while(!first.isEmpty()){int[]p=first.remove();q.add(new int[]{p[0],p[1],0});for(int d=0;d<4;d++){int a=p[0]+ds[d],b=p[1]+ds[d+1];if(a>=0&&a<n&&b>=0&&b<n&&!seen[a][b]&&grid[a][b]==1){seen[a][b]=true;first.add(new int[]{a,b});}}}while(!q.isEmpty()){int[]p=q.remove();for(int d=0;d<4;d++){int a=p[0]+ds[d],b=p[1]+ds[d+1];if(a>=0&&a<n&&b>=0&&b<n&&!seen[a][b]){if(grid[a][b]==1)return p[2];seen[a][b]=true;q.add(new int[]{a,b,p[2]+1});}}}return -1;}
}
